 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Every contiguous multi-cell run in a template row is a motif.
    patterns = []
    source_rows = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            run = row[start:c]
            if len(run) > 1:
                patterns.append((r, start, run))
                source_rows.add(r)

    # A singleton anywhere outside template rows is an anchor. Stamp its
    # matching motif so the anchor color occupies the same position in it.
    for r, row in enumerate(grid):
        if r in source_rows:
            continue
        for anchor_c, color in enumerate(row):
            if color == 0:
                continue
            candidates = [(pr, start, run) for pr, start, run in patterns if color in run]
            if not candidates:
                continue
            pr, start, run = min(candidates, key=lambda p: (abs(p[0] - r), p[1]))
            left = anchor_c - run.index(color)
            for i, value in enumerate(run):
                c = left + i
                if 0 <= c < w:
                    out[r][c] = value
    return out
