    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Every contiguous multi-cell run is a motif. Isolated colored cells are
    # anchors for the motif containing their color.
    motifs = []
    motif_cells = set()
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start > 1:
                motif = row[start:c]
                motifs.append(motif)
                for cc in range(start, c):
                    motif_cells.add((r, cc))

    for r, row in enumerate(grid):
        for anchor_c, color in enumerate(row):
            if color == 0 or (r, anchor_c) in motif_cells:
                continue
            motif = next((m for m in motifs if color in m), None)
            if motif is None:
                continue
            left = anchor_c - motif.index(color)
            for i, value in enumerate(motif):
                c = left + i
                if 0 <= c < w:
                    out[r][c] = value
    return out
